{
  "name": "@bangbang93/opencode-bash-file-read-guard",
  "version": "0.1.0",
  "description": "OpenCode plugin that blocks cat, head and tail so the model reads files with the read tool",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "bash-file-read-guard"
  ],
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "NOTICE.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": "^2.4.2"
  },
  "scripts": {
    "test": "node --test index.test.ts",
    "test:bun": "bun test",
    "typecheck": "tsc --noEmit -p tsconfig.json"
  }
}

import { Plugin } from "@opencode/plugin"

// The tool is registered as `shell`; `bash` is accepted as the name models commonly use for it.
const SHELL_TOOLS = new Set(["shell", "bash"])
// A path that is not an option and contains no pipe, `&` or `;`.
const FILE = String.raw`[^\s|&;-][^\s|&;]*`
const BARE_READS = [
  new RegExp(String.raw`^\s*cat\s+${FILE}\s*$`),
  new RegExp(String.raw`^\s*(?:head|tail)\s+(?:-n\s+\d+\s+)?${FILE}\s*$`),
]

const WARNING =
  "Use the read tool instead of `cat`, `head` or `tail` to read a file: it numbers each line, reads large files in sections, and also opens images and PDFs."

export default Plugin.define({
  id: "bash-file-read-guard",
  async setup(ctx) {
    await ctx.tool.hook("execute.before", async (event) => {
      if (!SHELL_TOOLS.has(event.tool)) return
      const { command } = event.input as { command?: unknown }
      if (typeof command === "string" && BARE_READS.some((read) => read.test(command))) throw new Error(WARNING)
    })
  },
})
